import{z as s,x as A,o as t,c as d,q as l,j as n,D as e,d as r,s as i,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"波动率卖方与尾部","description":"","frontmatter":{"title":"波动率卖方与尾部","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/short-vol-tail.md","filePath":"quant/short-vol-tail.md","lastUpdated":1791063341000}'),h={name:"quant/short-vol-tail.md"};function p(m,a,u,c,f,C){const B=A("Mermaid");return t(),d("div",null,[a[2]||(a[2]=l('<h1 id="波动率卖方与尾部" tabindex="-1">波动率卖方与尾部 <a class="header-anchor" href="#波动率卖方与尾部" aria-label="Permalink to &quot;波动率卖方与尾部&quot;">​</a></h1><div class="epigraph"><p>卖出隐含相对已实现的差额，平均能收到波动风险溢价；同一笔仓位在左尾是杠杆空头凸性，不是「稳定的类债券息票」。</p><footer>—— Bakshi and Kapadia, Review of Financial Studies, 2003；方差定价见 Carr–Madan 与方差互换课</footer></div><p><a href="/quant/capital-structure-arb">上一课</a>的跨要求权残差里已经混着隐含波动。本课把<strong>波动率卖方</strong>单独放到策略地图上：卖方差、卖跨式、卖 VIX 期货曲线，以及对称的<strong>买尾部</strong>。主干 <a href="/quant/variance-swap-vix">方差互换与 VIX</a>、<a href="/quant/gamma-theta-tradeoff">Gamma–Theta</a>、<a href="/quant/vix-term-structure-trade">VIX 期限结构</a> 已写合约与希腊字母。本课只补策略族：溢价从哪来、何时该当成 ARP、何时只是拥挤的空头凸性。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>期权隐含波动平均高于随后已实现，delta 对冲的多头期权期望为负（Bakshi–Kapadia）。卖方把这块叫做「波动风险溢价」。问题是路径：溢价在多数月份像收息，在少数月份像缺口。把卖方净值的夏普当产品承诺，等于用正偏的抽样误差卖左尾。买尾部（OTM 看跌、VIX 看涨、方差上端）是反向：长期负 carry，危机凸性。地图必须把两者分开记账，不能在「另类收益」里只报卖方。</p><p><span class="marginnote">数字感受一下路径问题：卖 1 个月平值跨式可能一连几十个月每月收 1%–2% 权利金，看起来平滑；但 2020 年 3 月那样的单月缺口可以吞掉几年的累计利润。夏普是按月平均算的，账户净值却是复利相乘——少数左尾月份的权重远比平均值大。</span></p><p>与宏观、RV：短波动常被当成无关的第三条腿。2018 年 volmageddon、2020 年 3 月说明短波动与风险平价、趋势的去杠杆可以同步。</p><h3 id="不要把-theta-当-alpha" tabindex="-1">不要把 Theta 当 alpha <a class="header-anchor" href="#不要把-theta-当-alpha" aria-label="Permalink to &quot;不要把 Theta 当 alpha&quot;">​</a></h3><p>持有空 Gamma 每天收 Theta，这是会计，不是预测力。公平溢价已经在隐含里。只有隐含相对随后实现的偏差超出融资与缺口补偿时，才有可卖的边缘，见 <a href="/quant/net-edge">净边缘</a>。杠杆 ETF 的每日重置是另一条 Jensen，见 <a href="/quant/leverage-volatility-drag">杠杆与波动拖累</a>，不要和卖方差混成同一个「波动产品」。</p><p><span class="marginnote">尾部对冲的失败模式是「买了但不在该在的行权价与期限上」。指数看跌的最贵处往往是拥挤的 5%–10% 一个月，真正的缺口可能更左或更长。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>卖方：方差互换、delta 中性跨式、看跌价差、VIX 期货展期。买方：OTM 看跌、看跌价差、VIX 凸性。预算：用情景缺口（实现波动跳到 \\(x\\)）而不是历史 VaR。容量：场内期权冲击与做市商对冲流会反噬，见拥挤课。报告：分开「收溢价月份」与「付凸性月份」的贡献。</p><p><span class="marginnote">术语翻译：「负 carry」指持有的每一天都在慢性失血——尾部对冲的看跌期权每天衰减 theta，危机不来就一直亏小钱；换到的是危机日的凸性爆发。卖方恰成镜像：每天进小钱，危机日一次吐大的。</span></p>',13)),(t(),n(o,null,{default:e(()=>[i(B,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20GOAL%7B%22%E8%A6%81%E7%AB%99%E5%88%B0%E6%9B%B2%E7%BA%BF%E7%9A%84%E5%93%AA%E4%B8%80%E7%AB%AF%3F%22%7D%0A%20%20GOAL%20--%3E%7C%22%E6%94%B6%E6%BA%A2%E4%BB%B7%22%7C%20S1%5B%22%E6%96%B9%E5%B7%AE%E4%BA%92%E6%8D%A2%20%2F%20delta%20%E4%B8%AD%E6%80%A7%E8%B7%A8%E5%BC%8F%22%5D%0A%20%20GOAL%20--%3E%7C%22%E6%94%B6%E6%BA%A2%E4%BB%B7%22%7C%20S2%5B%22%E7%9C%8B%E8%B7%8C%E4%BB%B7%E5%B7%AE%20%2F%20VIX%20%E6%9C%9F%E8%B4%A7%E5%B1%95%E6%9C%9F%22%5D%0A%20%20GOAL%20--%3E%7C%22%E4%B9%B0%E5%87%B8%E6%80%A7%22%7C%20B1%5B%22OTM%20%E7%9C%8B%E8%B7%8C%20%2F%20VIX%20%E7%9C%8B%E6%B6%A8%22%5D%0A%20%20S1%20--%3E%20BUD%5B%22%E7%94%A8%E6%83%85%E6%99%AF%E7%BC%BA%E5%8F%A3%E5%AE%9A%E9%A2%84%E7%AE%97%2C%20%E4%B8%8D%E7%94%A8%E5%8E%86%E5%8F%B2%20VaR%22%5D%0A%20%20S2%20--%3E%20BUD%0A%20%20B1%20--%3E%20BUD%0A%20%20BUD%20--%3E%20REP%5B%22%E5%88%86%E5%BC%80%E6%8A%A5%E5%91%8A%3A%20%E6%94%B6%E6%BA%A2%E4%BB%B7%E6%9C%88%20%E4%B8%8E%20%E4%BB%98%E5%87%B8%E6%80%A7%E6%9C%88%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"风险厌恶与做市商库存使隐含 > 实现的均值。卖方提供保险，买方付保费。拥挤的卖方把保费压薄，剩下缺口风险。尾部买方若只买拥挤行权价，付的是他人的库存转移，不是自己的凸性。",-1)),(t(),n(o,null,{default:e(()=>[i(B,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20IV%5B%22%E9%9A%90%E5%90%AB%E7%9B%B8%E5%AF%B9%E5%B7%B2%E5%AE%9E%E7%8E%B0%22%5D%20--%3E%20Short%5B%22%E5%8D%96%E6%96%B9%20%E6%94%B6%E6%BA%A2%E4%BB%B7%22%5D%0A%20%20IV%20--%3E%20Tail%5B%22%E4%B9%B0%E6%96%B9%20%E4%BB%98%20carry%22%5D%0A%20%20Short%20--%3E%20Gap%5B%22%E5%B7%A6%E5%B0%BE%E7%BC%BA%E5%8F%A3%22%5D%0A%20%20Tail%20--%3E%20Gap%0A%20%20Crowd%5B%22%E6%8B%A5%E6%8C%A4%22%5D%20--%3E%20Short%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写未对冲的裸卖出作为「增强收益」建议。个股短波动还有借券与跳跃违约。评价必须含最坏月份，不能只报扣掉危机后的夏普。</p><p><span class="marginnote">常见误区：把卖跨式的月度正收益当成「类债券票息」。债券的最大损失通常有界（违约回收），而空 gamma 在市场跳空时的损失没有上限；两者夏普数字可以相近，风险性质完全不同，所以评价必须看最差月份而非平均月份。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>短波动收的是波动风险溢价，付的是左尾凸性；二者必须分报。</li><li>Theta 是会计，不是 alpha。</li><li>与风险平价、杠杆重置不是同一产品。</li><li>出处：Bakshi and Kapadia, <em>RFS</em>, 2003；复制与 VIX 见 Carr–Madan 及方差互换课。</li></ul>',5))])}const D=s(h,[["render",p]]);export{_ as __pageData,D as default};
